import React, { useEffect, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import "./optimizevideo.css";

const OptimizeVideo = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const [videoPath, setVideoPath] = useState("");
  const [message, setMessage] = useState("");

  useEffect(() => {
    if (location.state) {
      const { videoURL, results = {} ,localVideoPath,selectedFeatures} = location.state;
      console.log("Received Results:", results);
      console.log(VideoPath)

      const audioProcessedPath = results.audio_processing?.enhanced_video_path;
      const videoOptimizedPath = results.video_upscaling?.output_path;

      const selectedPath = audioProcessedPath || videoOptimizedPath;
      if (selectedPath) {
        const filename = selectedPath.split('\\').pop();
        if (filename) {
          setVideoPath(`http://127.0.0.1:8000/media/${filename}`);
          setMessage("Video processing completed successfully!");
        }
      } else {
        setMessage("No processed video available.");
      }
    }
  }, [location.state]);

  const handleDownload = () => {
    if (videoPath) {
      const link = document.createElement("a");
      link.href = videoPath;
      link.download = "optimized-video.mp4";
      link.click();
    }
  };

  return (
    <div className="clipping-app">
      <header className="header">
        <h1 className="logo">
          <span className="bold">Channel-</span>
          <span className="highlight">IQ</span>
        </h1>
        <nav className="nav">
          <a href="#clipper">Clipper</a>
          <a href="#pricing">Pricing</a>
          <button className="sign-in">Sign in</button>
          <button className="sign-up">Sign up</button>
          <button
            className="home-button"
            onClick={() => navigate('/clipper')}
          >
            Home
          </button>
        </nav>
      </header>

      <div className="optimized-video-page">
        <header className="page-header">
          <h1>Optimized Video Output</h1>
          <p>{message}</p>
        </header>
        <div className="video-output">
          {videoPath ? (
            <video className="optimized-video" controls src={videoPath}>
              Your browser does not support the video tag.
            </video>
          ) : (
            <p>No optimized video available.</p>
          )}
          {videoPath && (
            <div className="action-buttons">
              <button className="download-button" onClick={handleDownload}>
                Download Video
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default OptimizeVideo;
